"""Actual fitted source facts to a separate base application planner; no teacher decisions."""
import json,sys,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from country_persona.io import read_jsonl,write_jsonl,write_json,sha256,digest

def main():
    old=ROOT/'data/prepared/actual-compact-planner-20261007-v1';dest=ROOT/'data/prepared/source-status-application-block-20261007-v1';assert not dest.exists()
    oldcase=list(read_jsonl(old/'cases.jsonl'))[0];text=oldcase['prompt'][1]['content'];note=text.split('CURRENT HYPOTHETICAL NOTE:\n',1)[1].split('\n\nQuestions to cover',1)[0]
    parent=ROOT/'runs/aurora-source-status-fit-20261007-v2';review=json.loads((parent/'inspection.json').read_text());assert review['all_outputs_read_complete'] and review['transcript_sha256']==sha256(parent/'transcript.jsonl')
    row=list(read_jsonl(parent/'transcript.jsonl'))[0];assert row['id']=='ukraine24-fra-source-only-planner' and len(row['output'].split())==207
    prompt='COUNTRY/ROLE/DATE: France, national Council de Rivière,25 July2024.\n\nACTUAL MODEL-GENERATED DOCUMENTED SOURCE POINTS (not teacher decisions):\n'+row['output']+'\n\nCURRENT HYPOTHETICAL NOTE (unchanged):\n'+note+'\n\nTASK: Return at most70 ordinary English words under Analytical decisions and Authority. Assess which current Z clauses are retained and which still conflict with the documented positions; give at least two concrete relevant operational directions, one practical competing cost, and an explicit answer about official Z endorsement and a future Council vote. Keep actual recorded French commitments; recommendations are analytical. Do not restate the source block or treat desired source corrections as already present in Z. No invented national condition or authority. No supplied decisions or answers.'
    c={'id':'ukraine24-fra-actual-facts-application-block','country_iso3':'FRA','family':'ukraine24','condition':'base_application_from_actual_fitted_facts','prompt':[oldcase['prompt'][0],{'role':'user','content':prompt}]}
    cfg=json.loads((ROOT/'configs/posttraining/qwen35-source-status-base-20261007-v1.json').read_text());cfg.update(pack=str(dest.relative_to(ROOT)),eval_cases=1,task_max_words=70,kind='actual_source_facts_separate_application_planner')
    from transformers import AutoTokenizer
    tok=AutoTokenizer.from_pretrained(cfg['model_path'],local_files_only=True);ids=tok.apply_chat_template(c['prompt'],tokenize=True,return_dict=False,add_generation_prompt=True,enable_thinking=False);c.update(input_ids=ids,input_ids_digest=digest(ids));assert len(ids)+2048<=8192
    original=json.loads((old/'criteria.json').read_text());crit={**original,'source_units':{'ukraine24':{'FRA':{}}},'policy':'Separate6application-unit/70word diagnostic; full14unit endpoint remains unchangedoriginalcriteria, actual207wordsource block alreadycheckedall8. No applicationtraining.'}
    dest.mkdir();write_jsonl(dest/'cases.jsonl',[c]);write_json(dest/'criteria.json',crit);shutil.copy2(old/'sources.json',dest/'sources.json');shutil.copy2(old/'presentation-criteria.json',dest/'presentation-criteria.json');write_json(dest/'actual-source-points.json',{'row':row,'run':str(parent.relative_to(ROOT)),'run_sha256':sha256(parent/'run.json'),'transcript_sha256':sha256(parent/'transcript.jsonl'),'inspection_sha256':sha256(parent/'inspection.json'),'source_point_content_unedited':True})
    write_json(dest/'provenance.json',{'source':row['id'],'actual_facts_not_teacher_or_hand_rewrite':True,'hypothetical_note_unchanged':note,'selected_after_full14_raw_inspection':sha256(ROOT/'runs/aurora-source-status-application-20261007-v1/inspection.json'),'scope':'Adaptive exposeddevelopment: familiarfittedsource, newapplicationinput/layout. Base receivesactualknowncorrectsourcefacts, noanalyticalanswers. Notpersona/OOD/independentreview gain. Comparecompletecomposedendpoint underoriginal14criteria ifblockapproved.'});shutil.copy2(__file__,dest/'builder-code.py')
    write_json(dest/'manifest.json',{'created_at':datetime.now(timezone.utc).isoformat(),'files_sha256':{p.name:sha256(p) for p in dest.iterdir()},'training_authorized_for_this_pack':False,'training_examples':0,'eval_cases':1,'source_scope':crit['policy']});write_json(dest/'manual-inspection.json',{'all_selected_texts_read_complete':True,'manifest_sha256':sha256(dest/'manifest.json'),'scope':'Uneditedactual207wordsourcefacts/currentZ/questions/6unchangedcriteria/inputcontract allhandread. Source8alreadychecked, endpoint14required. Sameauthor/grader.'});write_json(ROOT/'configs/posttraining/qwen35-source-status-application-block-base-20261007-v1.json',cfg);print(json.dumps({'facts_words':207,'block_words':70,'input_tokens':len(ids),'new_steps':0}))

